import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../../services/auth.service';

@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.css']
})
export class NavbarComponent {
  isMobileMenuOpen = false;

  constructor(
    private router: Router,
    private authService: AuthService
  ) { }

  toggleMobileMenu() {
    this.isMobileMenuOpen = !this.isMobileMenuOpen;
  }

  closeMobileMenu() {
    this.isMobileMenuOpen = false;
  }

  logout() {
    this.authService.logout();
    this.router.navigate(['/login']);
  }
}
<nav class="navbar">
  <div class="navbar-container">
    <div class="navbar-brand">
      <a href="/">
        <span class="brand-logo">NEXO</span>
      </a>
    </div>

    <button class="hamburger" (click)="toggleMobileMenu()" [class.active]="isMobileMenuOpen">
      <span></span>
      <span></span>
      <span></span>
    </button>

    <ul class="navbar-menu" [class.open]="isMobileMenuOpen">
      <li><a href="/comunidades" (click)="closeMobileMenu()">Comunidades</a></li>
      <li><a href="/eventos" (click)="closeMobileMenu()">Eventos</a></li>
      <li class="navbar-menu-user">
        <button class="logout-btn" (click)="logout()">Cerrar sesión</button>
      </li>
    </ul>
  </div>
</nav>
